import React, { useState } from 'react';
import { Card, Input, Button, List, Typography, Spin } from 'antd';
import { SendOutlined } from '@ant-design/icons';
import axios from 'axios';

const { Text } = Typography;

const Chat = () => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState([
    { type: 'bot', text: 'O que você quer monitorar?\n\nPode me dizer temas, assuntos ou empresas que gostaria de extrair um relatório de comunicação.' }
  ]);
  const [loading, setLoading] = useState(false);

  const handleSend = async () => {
    if (!input.trim()) return;
    setMessages(prev => [...prev, { type: 'user', text: input }]);
    setLoading(true);
    try {
      const res = await axios.post('http://localhost:4000/api/noticias', { termo: input });
      const noticias = res.data;
      if (noticias.length === 0) {
        setMessages(prev => [...prev, { type: 'bot', text: 'Nenhuma notícia encontrada para esse tema.' }]);
      } else {
        const resumo = `Encontrei ${noticias.length} notícias. Veja as mais recentes abaixo:`;
        setMessages(prev => [...prev, { type: 'bot', text: resumo }, ...noticias.slice(0, 5).map(n => ({ type: 'news', noticia: n }))]);
      }
    } catch (e) {
      setMessages(prev => [...prev, { type: 'bot', text: 'Erro ao buscar notícias.' }]);
    }
    setLoading(false);
    setInput('');
  };

  return (
    <Card style={{ width: 500, background: '#f3eaff' }}>
      <List
        dataSource={messages}
        renderItem={msg =>
          msg.type === 'news' ? (
            <List.Item style={{ background: '#fff', margin: '8px 0', borderRadius: 8 }}>
              <div>
                <Text strong>{msg.noticia.title}</Text>
                <div><Text type="secondary">{msg.noticia.source.name} - {new Date(msg.noticia.publishedAt).toLocaleDateString()}</Text></div>
                <div>{msg.noticia.description}</div>
                <a href={msg.noticia.url} target="_blank" rel="noopener noreferrer">Ler mais</a>
              </div>
            </List.Item>
          ) : (
            <List.Item style={{ justifyContent: msg.type === 'user' ? 'flex-end' : 'flex-start', background: msg.type === 'user' ? '#e6f7ff' : 'transparent', borderRadius: 8, margin: '8px 0' }}>
              <Text>{msg.text}</Text>
            </List.Item>
          )
        }
      />
      {loading && <Spin style={{ margin: '10px 0' }} />}
      <Input.Group compact style={{ marginTop: 16 }}>
        <Input
          style={{ width: '85%' }}
          placeholder="Digite um tema, empresa ou assunto..."
          value={input}
          onChange={e => setInput(e.target.value)}
          onPressEnter={handleSend}
          disabled={loading}
        />
        <Button type="primary" icon={<SendOutlined />} onClick={handleSend} disabled={loading} />
      </Input.Group>
    </Card>
  );
};

export default Chat;
